begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();aid uuid;foreign_app uuid;g uuid:=gen_random_uuid();a uuid:=gen_random_uuid();p jsonb;r jsonb;b jsonb;retry jsonb;
 k text:=repeat('1',64);other_key text:=repeat('2',64);session_id uuid:=gen_random_uuid();
begin
 insert into auth.users(id) values(u),(v);
 insert into public.jobs(id,canonical_url,employer) values('artifact-fixture','https://example.com/artifact','{}');
 insert into public.applications(user_id,job_id) values(u,'artifact-fixture') returning id into aid;
 insert into public.applications(user_id,job_id) values(v,'artifact-fixture') returning id into foreign_app;
 insert into public.preparation_plans(application_id,user_id,version,plan) values(aid,u,1,'{"applicationId":"artifact-fixture","tasks":[{"id":"practice","title":"Practice","minutes":15,"completed":false}]}');
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Artifacts',k,array['workspace:read','drafts:write'],now()+interval '1 hour'),(v,'Other',other_key,array['workspace:read','drafts:write'],now()+interval '1 hour');
 perform set_config('test.uid',u::text,true);
 p:=jsonb_build_object('id',g,'expectedVersion',0,'title','Database depth','objective','Explain indexes','active',true,'tasks',jsonb_build_array(jsonb_build_object('id','index','title','Index walkthrough','detail','Predict scan costs','minutes',30,'targetDate',current_date::text),jsonb_build_object('id','missing','title','Needs material','detail','Not yet prepared','minutes',15,'targetDate',current_date::text)));
 r:=public.agent_dispatch(k,'learning.save',p);
 if r->>'version'<>'1' or public.artifact_action('learning.save',p)<>r then raise exception 'Goal replay/transport mismatch';end if;
 p:=jsonb_build_object('id',a,'expectedVersion',0,'title','Index walkthrough','purpose','Understand tradeoffs','kind','explainer','format','html','body','<button onclick="this.textContent=''Done''">Try</button>','sources',jsonb_build_array(jsonb_build_object('title','Official docs','url','https://example.com/docs','observedAt',current_date::text)),'links',jsonb_build_array(jsonb_build_object('goalId',g,'taskId','index'),jsonb_build_object('applicationId',aid,'taskId','practice')));
 r:=public.artifact_action('artifacts.save',p);
 if r->>'version'<>'1' or r->>'path' not like '/career-toolkit/?artifact=%' then raise exception 'Not saved';end if;
 if public.agent_dispatch(k,'artifacts.save',p)<>r then raise exception 'Cross transport replay';end if;
 if public.agent_dispatch(k,'artifacts.read',jsonb_build_object('id',a))->'content'->>'body'<>p->>'body' then raise exception 'Lost interactive content';end if;
 b:=public.agent_dispatch(k,'artifacts.list','{"query":"tradeoffs"}');
 if jsonb_array_length(b->'items')<>1 or b->'items'->0->'content' ? 'body' then raise exception 'Metadata list/search failed';end if;
 begin perform public.agent_dispatch(other_key,'artifacts.read',jsonb_build_object('id',a));raise exception 'Foreign artifact';exception when no_data_found then null;end;
 if jsonb_array_length(public.agent_dispatch(other_key,'artifacts.list','{}')->'items')<>0 then raise exception 'Artifact list leak';end if;
 begin perform public.agent_dispatch(k,'artifacts.save',jsonb_set(p,'{links}',jsonb_build_array(jsonb_build_object('applicationId',foreign_app,'taskId','practice'))));raise exception 'Foreign task';exception when no_data_found then null;end;
 begin perform public.agent_dispatch(k,'artifacts.save',jsonb_set(p,'{title}','"Changed retry"'));raise exception 'Changed retry';exception when serialization_failure then null;end;
 begin perform public.artifact_action('artifacts.save',p||'{"extra":true}');raise exception 'Unknown payload';exception when invalid_parameter_value then null;end;
 p:=p||'{"expectedVersion":1,"body":"Updated interactive content"}';
 r:=public.agent_dispatch(k,'artifacts.save',p);
 if r->>'version'<>'2' then raise exception 'No revision';end if;
 if public.artifact_action('artifacts.read',jsonb_build_object('id',a,'version',1))->'content'->>'body'='Updated interactive content' then raise exception 'History overwritten';end if;
 b:=private.preparation_planner_read_owned(u);
 if jsonb_array_length(b->'learningGoals')<>1 or jsonb_array_length(b->'artifacts')<>1 then raise exception 'Planner missing goals/materials';end if;
 retry:=jsonb_build_object('sessionId',session_id,'minutes',15,'targets',jsonb_build_array(jsonb_build_object('goalId',g,'taskId','index','expectedVersion',1),jsonb_build_object('applicationId',aid,'taskId','practice','expectedVersion',1)));
 b:=public.agent_dispatch(k,'preparation.session.complete',retry);
 if (select count(*) from public.preparation_sessions where user_id=u)<>1 then raise exception 'Duplicate ledger';end if;
 if b->'learningGoals'->0->>'version'<>'2' or b->'learningGoals'->0->'goal'->'tasks'->0->>'completed'<>'false' then raise exception 'Partial learning credit';end if;
 if (select plan->'tasks'->0->>'completed' from public.preparation_plans where application_id=aid)<>'true' then raise exception 'Interview not credited';end if;
 if public.complete_preparation_session(session_id,15,retry->'targets')<>b then raise exception 'Session replay mismatch';end if;
 begin perform public.agent_dispatch(k,'preparation.session.complete',retry||jsonb_build_object('sessionId',gen_random_uuid()));raise exception 'Stale session';exception when serialization_failure then null;end;
 b:=public.complete_preparation_session(gen_random_uuid(),15,jsonb_build_array(jsonb_build_object('goalId',g,'taskId','index','expectedVersion',2)));
 if b->'learningGoals'->0->'goal'->'tasks'->0->>'completed'<>'true' then raise exception 'Learning not completed';end if;
 p:=jsonb_build_object('id',g,'expectedVersion',3,'title','Replanned','objective','Explain indexes','active',true,'tasks','[]'::jsonb);
 b:=public.artifact_action('learning.save',p);
 if jsonb_array_length(b->'goal'->'tasks')<>1 or b->'goal'->'tasks'->0->>'completed'<>'true' then raise exception 'Completed work discarded';end if;
 r:=public.artifact_action('artifacts.archive',jsonb_build_object('id',a,'expectedVersion',2,'archived',true));
 if jsonb_array_length(public.agent_dispatch(k,'artifacts.list','{}')->'items')<>0 or jsonb_array_length(private.preparation_planner_read_owned(u)->'artifacts')<>0 then raise exception 'Archive still active';end if;
 if public.agent_dispatch(k,'artifacts.read',jsonb_build_object('id',a))->>'archived'<>'true' then raise exception 'Archived link lost';end if;
 perform public.agent_dispatch(k,'artifacts.archive',jsonb_build_object('id',a,'expectedVersion',3,'archived',false));
 update private.agent_connections set scopes=array['workspace:read'] where token_hash=k;
 begin perform public.agent_dispatch(k,'artifacts.archive',jsonb_build_object('id',a,'expectedVersion',4,'archived',true));raise exception 'Scope bypass';exception when insufficient_privilege then null;end;
 update private.agent_connections set revoked_at=now() where token_hash=k;
 begin perform public.agent_dispatch(k,'learning.read','{}');raise exception 'Revoked connection';exception when invalid_authorization_specification then null;end;
 perform set_config('test.uid',v::text,true);
 begin perform public.artifact_action('artifacts.read',jsonb_build_object('id',a));raise exception 'Browser owner bypass';exception when no_data_found then null;end;
end $$;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();a uuid;kind text;p jsonb;r jsonb;k text:=repeat('a',64);bad text:=repeat('b',64);
begin
 insert into auth.users(id) values(u),(v);
 insert into private.agent_connections(user_id,name,token_hash,scopes,expires_at) values(u,'Document test',k,array['workspace:read','drafts:write'],now()+interval '1 hour'),(v,'Foreign document test',bad,array['workspace:read','drafts:write'],now()+interval '1 hour');
 perform set_config('test.uid',u::text,true);
 foreach kind in array array['cover_letter','application_template'] loop
  a:=gen_random_uuid();
  p:=jsonb_build_object('id',a,'expectedVersion',0,'title','Application document','purpose','Private reusable material','kind',kind,'format','markdown','body','Review this text before use.','sources','[]'::jsonb,'links','[]'::jsonb);
  r:=public.artifact_action('artifacts.save',p);
  if public.agent_dispatch(k,'artifacts.save',p)<>r then raise exception 'Document cross-transport mismatch';end if;
  if jsonb_array_length(public.agent_dispatch(k,'artifacts.list',jsonb_build_object('kind',kind))->'items')<>1 then raise exception 'Document kind filter failed';end if;
  begin perform public.agent_dispatch(bad,'artifacts.read',jsonb_build_object('id',a));raise exception 'Foreign document read';exception when no_data_found then null;end;
  begin perform public.artifact_action('artifacts.save',p||'{"title":"Stale copy"}');raise exception 'Stale document overwrite';exception when serialization_failure then null;end;
  r:=public.agent_dispatch(k,'artifacts.save',p||'{"expectedVersion":1,"body":"Revised text"}');
  if r->>'version'<>'2' then raise exception 'Document version missing';end if;
  if public.artifact_action('artifacts.read',jsonb_build_object('id',a,'version',1))->'content'->>'body'<>'Review this text before use.' then raise exception 'Document history lost';end if;
 end loop;
end $$;
set local role authenticated;
select set_config('test.uid','22222222-2222-2222-2222-222222222222',true);
do $$ begin
 if exists(select 1 from public.career_artifacts) or exists(select 1 from public.career_artifact_revisions) or exists(select 1 from public.learning_goals) then raise exception 'RLS leak';end if;
 begin insert into public.learning_goals(id,user_id,goal) values(gen_random_uuid(),auth.uid(),'{}');raise exception 'Direct write';exception when insufficient_privilege then null;end;
 begin perform private.artifact_owned(auth.uid(),'learning.read','{}');raise exception 'Private helper bypass';exception when insufficient_privilege then null;end;
end $$;
set local role anon;
do $$ begin
 begin perform public.artifact_action('learning.read','{}');raise exception 'Anonymous read';exception when insufficient_privilege then null;end;
end $$;
rollback;
